mapper.select:
SELECT
    E.EDGE_ID,
    E.FOLDER_ID,
    E.SOURCE_MEMO_ID,
    E.TARGET_MEMO_ID,
    E.EDGE_TYPE,
    E.CREATED_AT
FROM BOARD_EDGE E
INNER JOIN MEMO_FOLDER F
    ON F.FOLDER_ID = E.FOLDER_ID
WHERE E.FOLDER_ID = #{folderId}
  AND F.USER_ID = #{userId}
  AND (
      (
          E.SOURCE_MEMO_ID = #{sourceMemoId}
          AND E.TARGET_MEMO_ID = #{targetMemoId}
      )
      OR
      (
          E.SOURCE_MEMO_ID = #{targetMemoId}
          AND E.TARGET_MEMO_ID = #{sourceMemoId}
      )
  )

mapper.delete:
DELETE FROM BOARD_EDGE
WHERE EDGE_ID = #{edgeId}
  AND FOLDER_ID IN (
      SELECT FOLDER_ID
      FROM MEMO_FOLDER
      WHERE USER_ID = #{userId}
  )
